// Mini-port of Python's argparse for exactly this parser:
//   prog [-h] --a A --b B
// -h/--help (nargs 0), --a and --b (required, one value each).
// Reproduces CPython argparse behavior for this parser: '=' form, unique-prefix
// abbreviation (with ambiguity errors), the negative-number matcher
// ^-\d+$|^-\d*\.\d+$, '--' separator handling, error messages and exit codes.
import { writeSync } from 'node:fs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
const PREFIX_CHARS = '-';

// Python repr() of a string, sufficient for the 'ignored explicit argument'
// error message (covers quotes, backslash, standard escapes, control chars).
function pyRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (cp < 0x20 || cp === 0x7f) out += '\\x' + cp.toString(16).padStart(2, '0');
    else out += ch;
  }
  return out + quote;
}

export function parseArgs(argv, prog) {
  const usage = `usage: ${prog} [-h] --a A --b B\n`;
  const help = usage +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n';

  function error(message) {
    writeSync(2, usage + `${prog}: error: ${message}\n`);
    process.exit(2);
  }

  function printHelp() {
    writeSync(1, help);
    process.exit(0);
  }

  // Option definitions in definition order.
  const options = [
    { strings: ['-h', '--help'], dest: 'help', nargs: 0 },
    { strings: ['--a'], dest: 'a', nargs: 1 },
    { strings: ['--b'], dest: 'b', nargs: 1 },
  ];
  // option_string -> action, insertion ordered (like argparse's dict).
  const optionStringActions = new Map();
  for (const opt of options) {
    for (const s of opt.strings) optionStringActions.set(s, opt);
  }

  const actionName = (opt) => opt.strings.join('/');

  // argparse._get_option_tuples
  function getOptionTuples(argString) {
    const result = [];
    const eq = argString.indexOf('=');
    const hasEq = eq !== -1;
    const optionPrefix = hasEq ? argString.slice(0, eq) : argString;
    const sep = hasEq ? '=' : null;
    const explicit = hasEq ? argString.slice(eq + 1) : null;
    if (argString[0] === '-' && argString[1] === '-') {
      // long option: unique-prefix abbreviation
      for (const [optionString, opt] of optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push([opt, optionString, sep, explicit]);
        }
      }
    } else {
      // short option: may be concatenated with its argument
      const shortPrefix = argString.slice(0, 2);
      const shortExplicit = argString.slice(2);
      for (const [optionString, opt] of optionStringActions) {
        if (optionString === shortPrefix) {
          result.push([opt, optionString, '', shortExplicit]);
        } else if (optionString.startsWith(optionPrefix)) {
          result.push([opt, optionString, sep, explicit]);
        }
      }
    }
    return result;
  }

  // argparse._parse_optional: returns
  //   null                                   -> positional ('A')
  //   [opt|null, optionString, sep, explicit] -> optional ('O'); opt null = unknown
  function parseOptional(argString) {
    if (argString === '') return null;
    if (argString[0] !== '-') return null;
    if (optionStringActions.has(argString)) {
      return [optionStringActions.get(argString), argString, null, null];
    }
    if (argString.length === 1) return null;
    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optStr = argString.slice(0, eq);
      if (optionStringActions.has(optStr)) {
        return [optionStringActions.get(optStr), optStr, '=', argString.slice(eq + 1)];
      }
    }
    const tuples = getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map((t) => t[1]).join(', ');
      error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (tuples.length === 1) {
      return tuples[0];
    }
    // no option matched; negative numbers are treated as positionals
    // (this parser has no options that look like negative numbers)
    if (NEGATIVE_NUMBER.test(argString)) return null;
    // tokens containing a space are treated as positionals
    if (argString.includes(' ')) return null;
    return [null, argString, null, null];
  }

  // argparse._match_argument for nargs 0 (pattern '()') and 1 (pattern '([A])').
  // Returns number of args matched, or null on no match.
  function matchArgument(opt, pattern) {
    if (opt.nargs === 0) return 0;
    return pattern[0] === 'A' ? 1 : null;
  }

  // Classify every token: 'O' optional, 'A' positional, '-' the '--' separator.
  const argPattern = [];
  const optionIndices = new Map(); // index -> option tuple
  let seenDoubleDash = false;
  for (let i = 0; i < argv.length; i++) {
    const s = argv[i];
    if (seenDoubleDash) {
      argPattern.push('A');
    } else if (s === '--') {
      seenDoubleDash = true;
      argPattern.push('-');
    } else {
      const tuple = parseOptional(s);
      if (tuple) {
        argPattern.push('O');
        optionIndices.set(i, tuple);
      } else {
        argPattern.push('A');
      }
    }
  }

  const extras = [];
  const values = { a: undefined, b: undefined };

  function consumeOptional(startIndex) {
    const argString = argv[startIndex];
    let [opt, optionString, sep, explicitArg] = optionIndices.get(startIndex);

    // unknown optional: the whole token goes to extras
    if (opt === null) {
      extras.push(argString);
      return startIndex + 1;
    }

    const actionTuples = [];
    let stop;
    while (true) {
      if (explicitArg !== null) {
        const argCount = matchArgument(opt, 'A');
        if (argCount === 0 && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
          // single-dash option that takes no arguments: try to parse more
          // single-dash options out of the tail of the option string
          if (sep || PREFIX_CHARS.includes(explicitArg[0])) {
            error(`argument ${actionName(opt)}: ignored explicit argument ${pyRepr(explicitArg)}`);
          }
          actionTuples.push([opt, [], optionString]);
          const char = optionString[0];
          optionString = char + explicitArg[0];
          if (optionStringActions.has(optionString)) {
            opt = optionStringActions.get(optionString);
            explicitArg = explicitArg.slice(1);
            if (explicitArg === '') {
              sep = null;
              explicitArg = null;
            } else if (explicitArg[0] === '=') {
              sep = '=';
              explicitArg = explicitArg.slice(1);
            } else {
              sep = '';
            }
          } else {
            extras.push(char + explicitArg);
            stop = startIndex + 1;
            break;
          }
        } else if (argCount === 1) {
          stop = startIndex + 1;
          actionTuples.push([opt, [explicitArg], optionString]);
          break;
        } else {
          error(`argument ${actionName(opt)}: ignored explicit argument ${pyRepr(explicitArg)}`);
        }
      } else {
        const start = startIndex + 1;
        const selected = argPattern.slice(start).join('');
        const argCount = matchArgument(opt, selected);
        if (argCount === null) {
          error(`argument ${actionName(opt)}: expected one argument`);
        }
        stop = start + argCount;
        actionTuples.push([opt, argv.slice(start, stop), optionString]);
        break;
      }
    }

    for (const [o, args] of actionTuples) {
      if (o.nargs === 0) printHelp();
      else values[o.dest] = args[0];
    }
    return stop;
  }

  // Main consume loop (no positionals are defined, so any 'A'/'-' tokens are extras).
  const maxOptionIndex = optionIndices.size ? Math.max(...optionIndices.keys()) : -1;
  let startIndex = 0;
  while (startIndex <= maxOptionIndex) {
    let nextOption = startIndex;
    while (nextOption <= maxOptionIndex && !optionIndices.has(nextOption)) nextOption++;
    if (startIndex !== nextOption) {
      for (let i = startIndex; i < nextOption; i++) extras.push(argv[i]);
      startIndex = nextOption;
    }
    startIndex = consumeOptional(startIndex);
  }
  for (let i = startIndex; i < argv.length; i++) extras.push(argv[i]);

  // required-argument check happens before the unrecognized-argument check
  const missing = [];
  for (const opt of options) {
    if (opt.nargs === 1 && values[opt.dest] === undefined) missing.push(opt.strings[0]);
  }
  if (missing.length) {
    error(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length) {
    error(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return { a: values.a, b: values.b };
}

